"""Generate a portable static site. Python standard library only."""
from pathlib import Path
from html import escape as e
import json, shutil, re

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
MENU=json.loads((ROOT/'data/menu.json').read_text())
ORDER='https://order.toasttab.com/online/con-azucar-cafe-630-k-street-suite-100'
MAP='https://www.google.com/maps/search/?api=1&query=630+K+St+%23100+Sacramento+CA+95814'
GALLERY_ALTS=['Two guests holding canned coffee at an outdoor event','A Café X guest holding a giant concha','A group sharing pieces of a Concha Gigante','Friends raising coffee and matcha cans together','Guests breaking into a giant concha at a celebration','A guest holding a tray of Café X drinks','A guest showing a can of Café X coffee','Two friends sharing drinks and a giant concha','A Café X team member with coffee and mini conchas','Sharing pan dulce at a Café X gathering','Cans of Café X coffee and matcha on a table','Friends celebrating with a Concha Gigante','Two Café X team members holding bags of mini conchas','Friends enjoying freshly baked concha together']
GALLERY=[('event-portrait.webp','Café X canned drinks raised together'),('event-wide.webp','Sharing a Concha Gigante at a community event'),('event-coffee.webp','Friends enjoying Café X drinks at an event')]+[(f'gallery-{i+1}.webp',alt) for i,alt in enumerate(GALLERY_ALTS)]
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir()
shutil.copytree(ROOT/'assets',OUT/'assets')
for file in ['styles.css','app.js']:shutil.copy(ROOT/file,OUT/file)
shutil.copytree(ROOT/'data',OUT/'data')

def image(file,alt,cls='',eager=False):
    return f'<img class="{cls}" src="{{BASE}}assets/images/{file}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async" '+('fetchpriority="high" ' if eager else '')+'width="1100" height="1100">'
def link(text,path,cls='button',external=False):
    return f'<a class="{cls}" href="{path if external else "{BASE}"+path}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}<span aria-hidden="true">↗</span></a>'
def head(title,active):
    nav=''.join(f'<a href="{{BASE}}{path}/"'+(' aria-current="page"' if active==path else '')+f'>{label}</a>' for path,label in [('ourstory','Our Story'),('menu','Menu'),('shop','Shop'),('gallery','Gallery'),('contact-10','Contact')])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | CAFÉX</title><meta name="description" content="Mexican coffee, fresh jugos, pan dulce, and community in downtown Sacramento. Explore Café X at 630 K Street."><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#143c2a"><meta property="og:title" content="CAFÉX · Energía Mexicana"><meta property="og:description" content="Mexican roots. Sacramento soul. A Café X concept by Vessel Archive."><meta property="og:type" content="website"><link rel="icon" href="{{BASE}}assets/images/logo.png"><link rel="preload" as="font" href="{{BASE}}assets/fonts/barlow-bold.ttf" type="font/ttf" crossorigin><link rel="stylesheet" href="{{BASE}}styles.css"><script>try{{let t=localStorage.getItem('cafex-theme');if(t==='dark'||t==='light')document.documentElement.dataset.theme=t}}catch(e){{}}</script><script src="{{BASE}}app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="{{BASE}}" aria-label="Café X home"><img src="{{BASE}}assets/images/logo.png" alt="CAFÉX Coffee & Juice Bar" width="96" height="86"></a><nav id="navigation" aria-label="Main navigation">{nav}</nav><div class="header-actions"><button class="theme-toggle" aria-label="Switch color theme" title="Switch color theme"><span aria-hidden="true">◐</span></button>{link('Order Online',ORDER,'button small',True)}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">+</span></button></div></header><main id="main">'''
def footer():
    return f'''</main><footer><div class="footer-top"><a class="footer-tag" href="{{BASE}}">HECHO CON<br>ORGULLO.</a><div><h2>Find your cafecito.</h2><a href="{MAP}" target="_blank" rel="noopener noreferrer">630 K St #100<br>Sacramento, CA 95814 ↗</a><a href="tel:+19169961306">916-996-1306</a></div><div><h2>Come by.</h2><p>Monday - Friday <span>7am - 6pm</span><br>Saturday - Sunday <span>7am - 8pm</span></p><a href="mailto:info@hechoencafex.com">info@hechoencafex.com</a></div><div><h2>Stay connected.</h2><a href="https://www.instagram.com/hechoencafex/" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="https://www.tiktok.com/@hechoencafex" target="_blank" rel="noopener noreferrer">TikTok ↗</a><a href="https://www.facebook.com/profile.php?id=61587903140849" target="_blank" rel="noopener noreferrer">Facebook ↗</a></div></div><div class="footer-bottom"><span>© 2026 CAFÉX</span><span>Website concept by <strong>Vessel Archive</strong></span><span>Demo experience</span></div></footer><dialog id="photo-dialog" aria-label="Photo viewer"><button class="dialog-close" aria-label="Close photo viewer">Close ×</button><button class="photo-prev" aria-label="Previous photo">←</button><figure><img id="dialog-image" alt=""><figcaption id="photo-caption"></figcaption></figure><button class="photo-next" aria-label="Next photo">→</button></dialog></body></html>'''
def intro(kicker,title,description):
    return f'<section class="page-intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro-copy">{description}</p></section>'
def visit():
    return f'''<section class="visit section-pad reveal"><div class="visit-heading"><p class="eyebrow">Downtown Sacramento</p><h2>YOUR TABLE<br>IS WAITING.</h2></div><div class="visit-info"><p>Come for a cafecito.<br>Stay for the compañía.</p><address>630 K St #100<br>Sacramento, CA 95814</address>{link('Get Directions',MAP,'button',True)}</div></section>'''
def home():
    return f'''<section class="hero"><div class="hero-copy"><p class="eyebrow">Mexican roots. Sacramento soul.</p><h1><span>ENERGÍA</span><span>MEXICANA.</span></h1><p class="hero-description">Coffee with roots. Flavor with feeling.<br>A little México in every moment.</p><div class="hero-actions">{link('View Menu','menu/','button')}<a class="text-link" href="{{BASE}}ourstory/">Our Story <span aria-hidden="true">↗</span></a></div></div><figure class="hero-media">{image('hero.webp','Mexican coffee, café de olla, and a pink concha with nopal cactus','',True)}</figure><div class="hero-bottom"><span>COFFEE & JUICE BAR</span><a href="{MAP}" target="_blank" rel="noopener noreferrer">630 K STREET, SACRAMENTO ↗</a></div></section>
<section class="manifesto section-pad reveal"><p class="eyebrow">Bienvenidos a Café X</p><h2>A LITTLE CAFECITO.<br>A WHOLE LOT OF <span class="accent-text">CULTURA.</span></h2><div class="manifesto-bottom"><span class="big-x" aria-hidden="true">X</span><p>From the coffee farms of Nayarit to the heart of Sacramento. We bring our roots to the table with Mexican coffee, fresh jugos, and pan dulce made for sharing.</p></div></section>
<section class="favorites section-pad reveal"><div class="section-title"><h2>FIND YOUR<br>NEW FAVORITO.</h2><a class="text-link" href="{{BASE}}menu/">Explore the full menu ↗</a></div><div class="flavor-tabs" role="group" aria-label="Explore menu favorites"><button class="active" aria-pressed="true" data-flavor="coffee">Cafecito</button><button aria-pressed="false" data-flavor="bakery">Pan Dulce</button><button aria-pressed="false" data-flavor="juice">Jugos</button><button aria-pressed="false" data-flavor="energy">Energy</button></div><div class="favorites-grid" aria-live="polite"><a class="favorite-primary" href="{{BASE}}menu/"><div class="image-wrap">{image('horchata-latte.webp','Horchata latte with cinnamon and espresso','favorite-image')}</div><div class="favorite-caption"><div><h3 class="favorite-name">Horchata Latte</h3><p class="favorite-description">Espresso meets house horchata. Your new morning ritual.</p></div><span aria-hidden="true">↗</span></div></a><a class="favorite-secondary" href="{{BASE}}menu/"><div class="image-wrap">{image('caf-de-olla.webp','Traditional café de olla in a Mexican clay mug','second-image')}</div><div class="favorite-caption"><div><h3 class="second-name">Café de Olla</h3><p class="second-description">Cinnamon, piloncillo, and a taste of home.</p></div><span aria-hidden="true">↗</span></div></a></div></section>
<section class="roots section-pad reveal"><figure>{image('event-wide.webp','The Café X community sharing a Concha Gigante')}</figure><div class="roots-copy"><p class="eyebrow">From MEX to SAC</p><h2>ROOTED IN<br>SOMETHING<br><span class="accent-text">REAL.</span></h2><p>Inspired by Zacatecas. Fueled by community. The X in CAFÉX brings Mexican tradition and modern café culture together.</p>{link('Our Story','ourstory/','button outline')}</div></section>
<section class="to-go section-pad reveal"><div class="to-go-copy"><h2>TAKE THE<br>ENERGÍA<br>WITH YOU.</h2><p>Your café favorites, freshly made and sealed to go. Coffee, matcha, jugos, and energy infusions. One can or a pack to share.</p>{link('Order Online',ORDER,'button',True)}</div><figure>{image('canned.webp','Café X canned drinks overlooking a Sacramento soccer field')}</figure></section>
<section class="moments section-pad reveal"><div class="section-title"><h2>GOOD COFFEE.<br>GREAT COMPANY.</h2><a class="text-link" href="{{BASE}}gallery/">See the gallery ↗</a></div><div class="moments-grid"><a href="{{BASE}}gallery/">{image('event-coffee.webp','Friends with Café X drinks')}</a><a href="{{BASE}}gallery/">{image('event-portrait.webp','Canned Café X drinks shared with friends')}</a></div><p class="moments-note">Pop-ups, celebrations, and the moments in between. Bring Café X to yours. <a href="{{BASE}}contact-10/?subject=Catering">Book Catering ↗</a></p></section>{visit()}'''
def story():
    return intro('Our Story','FROM MEX<br>TO SAC.','Mexican roots. A Sacramento home. Coffee that connects the two.')+f'''<section class="story-opening section-pad"><figure>{image('coffee.webp','Latte art being poured into a ceramic cup','',True)}</figure><div class="reveal"><h2>IT STARTS<br>WITH OUR ROOTS.</h2><p>CAFÉX brings Mexican coffee culture to downtown Sacramento. Our coffee comes from Nayarit, where generations of growers care for the land and the beans that make each cup possible.</p><p>Our founder’s roots in Zacatecas shape what we do: a place to gather, share something good, and feel at home.</p><p>The nopal in our identity stands for resilience and growth. The X is where Mexican heritage and the energy of a modern café meet.</p></div></section><section class="story-statement section-pad reveal"><h2>TRADITION IN EVERY CUP.<br><span class="accent-text">ORGULLO IN EVERYTHING.</span></h2></section><section class="story-grid section-pad">'''+''.join(f'<article class="reveal">{image(im,alt)}<h2>{title}</h2><p>{copy}</p></article>' for im,alt,title,copy in [
      ('coffee.webp','Freshly poured coffee','Tradition brewed daily.','Coffee sourced from Nayarit, roasted dark for a rich, full-bodied cup. A daily connection to the people and places behind it.'),
      ('juice.webp','Freshly poured red juice','Fresh from the mercado spirit.','Whole fruits and vegetables, pressed into vibrant jugos. Inspired by Mexican juice stands and made with locally sourced produce.'),
      ('pan-dulce.webp','Café X Concha Gigante','Pan dulce. Big feelings.','From mini conchitas to the Concha Gigante, our daily baked favorites bring sweetness to your cafecito and your table.'),
      ('vampiro.webp','Café X Vampiro energy drink','A different kind of energy.','Our Red Bull partnership brings fruit-forward energy infusions to the menu. Choose your flavor and keep your day moving.'),
      ('canned.webp','A selection of canned Café X drinks','Freshly made. Ready to go.','Coffee, matcha, jugos, and energy infusions sealed into cans. Take one along or share a four-pack or six-pack.')])+f'</section>{visit()}'
def menu_page():
    categories=''.join(f'<button data-category="{e(s["name"])}" aria-pressed="false">{e(s["name"])}</button>' for s in MENU)
    body=intro('The Menu','MADE WITH<br>MUCHO GUSTO.','Cafecitos, pan dulce, fresh jugos, and a little something for every mood.')+f'''<section class="menu-section section-pad"><div class="menu-tools"><label class="search-label"><span>Find your favorite</span><input id="menu-search" type="search" placeholder="Try horchata, concha, matcha…" autocomplete="off"></label>{link('Order Online',ORDER,'button',True)}</div><div class="category-filters" role="group" aria-label="Filter menu by category"><button class="active" data-category="all" aria-pressed="true">All</button>{categories}</div><p class="menu-note">Menu and prices from Café X. Final availability and pricing are confirmed when ordering.</p><p class="results-message sr-only" aria-live="polite"></p><div class="no-results" hidden><h2>No matches this time.</h2><p>Try another flavor or browse the full menu.</p><button class="button reset-filters">Show all items</button></div>'''
    for section in MENU:
        body+=f'<section class="menu-category" data-menu-category="{e(section["name"])}"><h2>{e(section["name"])}</h2><p class="category-description">{e(section.get("description",""))}</p><div class="menu-grid">'
        for item in section['items']:
            name=item['name'].rstrip('*'); desc=item.get('description',''); img=image(item['image'].replace('.webp','-thumb.webp'),name) if 'image' in item else '<div class="menu-monogram" aria-hidden="true">CAFÉX</div>'
            body+=f'<article class="menu-item" data-search="{e((name+" "+desc).lower())}">{img}<div><div class="menu-item-title"><h3>{e(name)}</h3><span>{e(item.get("price",""))}</span></div><p>{e(desc)}</p></div></article>'
        body+='</div></section>'
    return body+'</section>'
def gallery():
    return intro('Gallery','OUR PEOPLE.<br>OUR MOMENTS.','Coffee brings us together. Take a look at the pop-ups, celebrations, and people that make Café X.')+f'<div class="gallery-action section-pad">{link("Book Catering","contact-10/?subject=Catering","button")}</div><section class="gallery-grid section-pad">'+''.join(f'<button class="gallery-photo" data-photo="{i}" aria-label="Open photo {i+1}: {e(alt)}">{image(file,alt,eager=i<3)}<span aria-hidden="true">↗</span></button>' for i,(file,alt) in enumerate(GALLERY))+'</section>'+visit()
def contact():
    return intro('Contact','LET’S MAKE<br>A CONNECTION.','A question, a celebration, or just a hello. We’d love to hear from you.')+f'''<section class="contact-grid section-pad"><div class="contact-details"><h2>HECHO EN CAFÉX.</h2><a href="tel:+19169961306">916-996-1306 ↗</a><a href="mailto:info@hechoencafex.com">info@hechoencafex.com ↗</a><p>Planning an event? Tell us a little about it and we’ll help you bring the energía.</p>{image('event-portrait.webp','A gathering with Café X canned drinks')}</div><form id="contact-form"><div class="field-row"><label>First Name<input name="first-name" required autocomplete="given-name" maxlength="80"></label><label>Last Name<input name="last-name" required autocomplete="family-name" maxlength="80"></label></div><label>Email<input type="email" name="email" required autocomplete="email" maxlength="150"></label><label>Message<textarea name="message" rows="6" required maxlength="3000"></textarea></label><p class="form-note">This demo prepares your message in your email app. You can review it before sending.</p><button class="button" type="submit">Prepare Email <span aria-hidden="true">↗</span></button><p id="contact-status" role="status"></p></form></section><section class="location section-pad reveal"><h2>SEE YOU<br>ON K STREET.</h2><div><address>630 K St #100<br>Sacramento, CA 95814</address><dl><div><dt>Monday - Friday</dt><dd>7am - 6pm</dd></div><div><dt>Saturday - Sunday</dt><dd>7am - 8pm</dd></div></dl>{link('Get Directions',MAP,'button',True)}</div></section>'''
def shop():
    return f'''<section class="shop-hero section-pad"><div><p class="eyebrow">The Café X Shop</p><h1>GOOD THINGS<br>ARE BREWING.</h1><p class="intro-copy">Our online shop is coming soon. Be the first to hear what’s next.</p><form id="notify-form"><label for="notify-email">Email address</label><div class="notify-row"><input id="notify-email" name="email" type="email" required placeholder="you@example.com" autocomplete="email"><button class="button" type="submit">Notify Me ↗</button></div><p class="form-note">Opens an email request to Café X. You’ll review and send it from your email app.</p><p role="status" id="notify-status"></p></form><a class="text-link" href="{ORDER}" target="_blank" rel="noopener noreferrer">Order your café favorites now ↗</a></div><figure>{image('canned.webp','Fresh Café X canned coffee and juice','',True)}</figure></section>'''
pages=[('', 'Energía Mexicana',home),('ourstory','Our Story',story),('menu','Menu',menu_page),('gallery','Gallery',gallery),('contact-10','Contact',contact),('shop','Shop',shop),('category/all-products','Shop',shop)]
for route,title,fn in pages:
    folder=OUT/route;folder.mkdir(parents=True,exist_ok=True)
    base='../'*len(route.split('/')) if route else './'
    (folder/'index.html').write_text((head(title,route)+fn()+footer()).replace('{BASE}',base))
(OUT/'404.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Page not found | CAFÉX</title><style>body{margin:0;background:#143c2a;color:#f2f3e7;font-family:Arial,sans-serif;min-height:100dvh;display:grid;place-items:center}main{padding:32px;max-width:750px}p{line-height:1.6;color:#bac9b8}h1{font-size:clamp(48px,9vw,100px);line-height:.95;letter-spacing:-.05em;margin:30px 0}a{display:inline-block;margin-top:25px;background:#cbea75;color:#143c2a;padding:18px 24px;text-decoration:none}a:focus-visible{outline:3px solid #f2f3e7;outline-offset:5px}</style></head><body><main><p>CAFÉX / 404</p><h1>LOST YOUR<br>CAFECITO?</h1><p>This page isn’t on the menu. Let’s get you back to something good.</p><a id="return-home" href="/">Back to Home ↗</a></main><script>if(location.hostname.endsWith('.github.io'))document.getElementById('return-home').href='/DEMO-CAFE-X/';</script></body></html>''')
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(OUT/'.nojekyll').touch()
# Support GitHub Pages' default main/(root) publishing as well as dist uploads.
# Shared styles, scripts, fonts, images, and data already live at the root.
for generated in [*OUT.rglob('*.html'), OUT/'robots.txt', OUT/'.nojekyll']:
    destination=ROOT/generated.relative_to(OUT)
    destination.parent.mkdir(parents=True,exist_ok=True)
    shutil.copy2(generated,destination)
print(f'Built {len(pages)} pages + 404 in dist and the repository root')
